function getParamReason(paramName, customReason) {
    // If the user provided a custom reason (like your notes for ARSPD_USE or PTCH_TRIM_DEG), keep it
    if (customReason && customReason.trim() !== '') {
        return customReason.trim();
    }
    
    // Otherwise fallback to ArduPilot docs lookup table
    return ARDUPILOT_PARAM_REASONS[paramName] || "Modified tuning parameter";
}

// Example usage when generating HTML rows for your table:
function buildParamRow(paramName, defaultVal, actualVal, userNote) {
    const reason = getParamReason(paramName, userNote);
    return `
        <tr>
            <td><strong>${paramName}</strong></td>
            <td>${defaultVal}</td>
            <td>${actualVal}</td>
            <td>${reason}</td>
        </tr>
    `;
}

function addObjectiveRow(desc = "", priority = "Med") {
    const tbody = document.getElementById('objectivesTableBody');
    const idx = tbody.children.length + 1;
    const tr = document.createElement('tr');
    tr.innerHTML = `
        <td style="text-align: center;"><input type="checkbox" checked class="obj-check"></td>
        <td style="text-align: center; color:#94a3b8; font-weight:bold;">${idx}</td>
        <td><input type="text" class="styled-input obj-desc" value="${desc}" placeholder="Objective description..."></td>
        <td>
            <select class="styled-input obj-prio">
                <option value="High" ${priority === 'High' ? 'selected' : ''}>🔴 High Priority</option>
                <option value="Med" ${priority === 'Med' ? 'selected' : ''}>🟡 Med Priority</option>
                <option value="Low" ${priority === 'Low' ? 'selected' : ''}>🟢 Low Priority</option>
            </select>
        </td>
        <td style="text-align: center;"><button class="btn-del" onclick="this.closest('tr').remove()">✕</button></td>
    `;
    tbody.appendChild(tr);
}

// Array to hold data for autoTable export
const paramRows = [];

function addParamRow(paramName = "", defaultVal = "", actualVal = "", userNote = "") {
    const tbody = document.getElementById('paramsTableBody');
    const tr = document.createElement('tr');
    
    // Get the lookup reason or fallback note
    const reason = getParamReason(paramName, userNote);
    
    const escapeAttr = (str) => String(str).replace(/"/g, '&quot;').replace(/</g, '&lt;');
    
    tr.innerHTML = `
        <td><input type="text" class="styled-input param-name" value="${escapeAttr(paramName)}" placeholder="e.g. Q_ANGLE_MAX"></td>
        <td><input type="text" class="styled-input param-default" value="${escapeAttr(defaultVal)}" placeholder="Default"></td>
        <td><input type="text" class="styled-input param-val" value="${escapeAttr(actualVal)}" placeholder="Actual"></td>
        <td><input type="text" class="styled-input param-reason" value="${escapeAttr(reason)}" placeholder="Reason for change..."></td>
        <td style="text-align: center;"><button class="btn-del" type="button">✕</button></td>
    `;
    
    tr.querySelector('.btn-del').addEventListener('click', () => tr.remove());
    
    tbody.appendChild(tr);
}

// ─── BIN File Parsing & Firmware CRC / Version Recovery ───────────────────────
document.getElementById('binFile').addEventListener('change', async function() {
    if (!this.files.length) return;
    try {
        document.getElementById('statusBox').textContent = "⏳ Parsing Dataflash Log...";
        await parseBinFile(this.files[0]);
        
        document.getElementById('durationStat').textContent = flightInfo.duration.toFixed(1) + ' s';
        document.getElementById('maxAltStat').textContent = flightInfo.maxAlt.toFixed(1) + ' m';
        document.getElementById('maxSpeedStat').textContent = flightInfo.maxSpeed.toFixed(1) + ' m/s';
        document.getElementById('fwVersionStat').textContent = flightInfo.firmware;
        document.getElementById('vehicleTypeStat').textContent = flightInfo.vehicle;
        document.getElementById('imuSamplesStat').textContent = flightInfo.totalSamples;
        
        timeCrop.start = 0;
        timeCrop.end = flightInfo.duration;
        document.getElementById('timeStart').value = 0;
        document.getElementById('timeEnd').value = flightInfo.duration.toFixed(1);
        
        document.getElementById('timeSelectionCard').style.display = 'block';
        renderBaroTimeChart();
        
        filterTelemetryByTime();
        renderAllCharts();
        
        document.getElementById('generateBtn').disabled = false;
        document.getElementById('statusBox').textContent = "✅ Telemetry Loaded Successfully";
        document.getElementById('statusBox').style.background = "rgba(34, 197, 94, 0.2)";
        document.getElementById('statusBox').style.color = "#4ade80";
    } catch (err) {
        console.error("Parse Error: ", err);
        document.getElementById('statusBox').textContent = "❌ Error reading log file";
    }
});

async function parseBinFile(file) {
    const buffer = await file.arrayBuffer();
    const parser = new DataflashParser(false);
    const parsed = parser.processData(buffer, [
        'BARO', 'GPS', 'IMU', 'ARSP', 'ATT', 'CSRV', 'AETR', 'ESC', 'MSG', 'VER'
    ]);
    
    // 1. Extract Version & Git Hash CRC from MSG packet
    if (parsed?.messages?.MSG?.Message) {
        const msgs = Array.from(parsed.messages.MSG.Message);
        msgs.forEach(mStr => {
            if (typeof mStr === 'string') {
                if (mStr.includes('ArduPlane') || mStr.includes('ArduCopter') || mStr.includes('V4.')) {
                    flightInfo.firmware = mStr.trim();
                }
                if (mStr.includes('commit') || mStr.includes('hash') || mStr.includes('CRC')) {
                    flightInfo.gitHash = mStr.trim();
                }
            }
        });
    }
    
    let baseTime = 0;
    const extractSeries = (msgName, fieldName, scale = 1) => {
        const msg = parsed?.messages?.[msgName];
        if (!msg || !msg.time_boot_ms || !msg[fieldName]) return [];
        return Array.from(msg[fieldName]).map((v, i) => {
            const t = Number(msg.time_boot_ms[i]) / 1000;
            if (!baseTime) baseTime = t;
            return { timeAbs: t, time: t - baseTime, value: Number(v) * scale };
        }).filter(p => Number.isFinite(p.value));
    };
    
    rawTelemetry = {
        baroAlt: extractSeries('BARO[0]', 'Alt') || extractSeries('BARO', 'Alt'),
        gpsAlt: extractSeries('GPS[0]', 'Alt', 0.001) || extractSeries('GPS', 'Alt', 0.001),
        gpsSpd: extractSeries('GPS[0]', 'Spd') || extractSeries('GPS', 'Spd'),
        imuZ: extractSeries('IMU[0]', 'AccZ') || extractSeries('IMU', 'AccZ'),
        airspeed: extractSeries('ARSP[0]', 'Airspeed') || extractSeries('ARSP', 'Airspeed'),
        roll: extractSeries('ATT', 'Roll'),
        desRoll: extractSeries('ATT', 'DesRoll'),
        pitch: extractSeries('ATT', 'Pitch'),
        desPitch: extractSeries('ATT', 'DesPitch'),
        yaw: extractSeries('ATT', 'Yaw'),
        desYaw: extractSeries('ATT', 'DesYaw'),
        csrv1: extractSeries('CSRV[1]', 'Pos'),
        csrv2: extractSeries('CSRV[2]', 'Pos'),
        csrv4: extractSeries('CSRV[4]', 'Pos'),
        csrv9: extractSeries('CSRV[9]', 'Pos'),
        aetrAil: extractSeries('AETR', 'Ail'),
        aetrElev: extractSeries('AETR', 'Elev'),
        escRpm: {
            m5: extractSeries('ESC[4]', 'Rpm'),
            m2: extractSeries('ESC[5]', 'Rpm'),
            m3: extractSeries('ESC[6]', 'Rpm'),
            m4: extractSeries('ESC[7]', 'Rpm')
        },
        escCurr: {
            m5: extractSeries('ESC[4]', 'Curr'),
            m2: extractSeries('ESC[5]', 'Curr'),
            m3: extractSeries('ESC[6]', 'Curr'),
            m4: extractSeries('ESC[7]', 'Curr')
        },
        escTemp: {
            m5: extractSeries('ESC[4]', 'Temp'),
            m2: extractSeries('ESC[5]', 'Temp'),
            m3: extractSeries('ESC[6]', 'Temp'),
            m4: extractSeries('ESC[7]', 'Temp')
        }
    };
    
    if (rawTelemetry.baroAlt.length) {
        flightInfo.duration = rawTelemetry.baroAlt[rawTelemetry.baroAlt.length - 1].time;
        flightInfo.maxAlt = Math.max(...rawTelemetry.baroAlt.map(p => p.value));
    }
    if (rawTelemetry.gpsSpd.length) {
        flightInfo.maxSpeed = Math.max(...rawTelemetry.gpsSpd.map(p => p.value));
    }
    flightInfo.totalSamples = rawTelemetry.imuZ.length || rawTelemetry.baroAlt.length || 0;
}

// ─── Time Crop Logic ──────────────────────────────────────────────────────────
function applyTimeWindow() {
    const s = parseFloat(document.getElementById('timeStart').value) || 0;
    const e = parseFloat(document.getElementById('timeEnd').value) || flightInfo.duration;
    
    timeCrop.start = Math.max(0, s);
    timeCrop.end = Math.min(flightInfo.duration, e);
    
    filterTelemetryByTime();
    renderAllCharts();
}

function resetTimeWindow() {
    timeCrop.start = 0;
    timeCrop.end = flightInfo.duration;
    document.getElementById('timeStart').value = 0;
    document.getElementById('timeEnd').value = flightInfo.duration.toFixed(1);
    
    filterTelemetryByTime();
    renderAllCharts();
}

function filterTelemetryByTime() {
    const crop = (arr) => arr ? arr.filter(p => p.time >= timeCrop.start && p.time <= timeCrop.end) : [];
    
    filteredTelemetry = {
        baroAlt: crop(rawTelemetry.baroAlt),
        gpsAlt: crop(rawTelemetry.gpsAlt),
        gpsSpd: crop(rawTelemetry.gpsSpd),
        imuZ: crop(rawTelemetry.imuZ),
        airspeed: crop(rawTelemetry.airspeed),
        roll: crop(rawTelemetry.roll),
        desRoll: crop(rawTelemetry.desRoll),
        pitch: crop(rawTelemetry.pitch),
        desPitch: crop(rawTelemetry.desPitch),
        yaw: crop(rawTelemetry.yaw),
        desYaw: crop(rawTelemetry.desYaw),
        csrv1: crop(rawTelemetry.csrv1),
        csrv2: crop(rawTelemetry.csrv2),
        csrv4: crop(rawTelemetry.csrv4),
        csrv9: crop(rawTelemetry.csrv9),
        aetrAil: crop(rawTelemetry.aetrAil),
        aetrElev: crop(rawTelemetry.aetrElev),
        escRpm: {
            m5: crop(rawTelemetry.escRpm?.m5),
            m2: crop(rawTelemetry.escRpm?.m2),
            m3: crop(rawTelemetry.escRpm?.m3),
            m4: crop(rawTelemetry.escRpm?.m4)
        },
        escCurr: {
            m5: crop(rawTelemetry.escCurr?.m5),
            m2: crop(rawTelemetry.escCurr?.m2),
            m3: crop(rawTelemetry.escCurr?.m3),
            m4: crop(rawTelemetry.escCurr?.m4)
        },
        escTemp: {
            m5: crop(rawTelemetry.escTemp?.m5),
            m2: crop(rawTelemetry.escTemp?.m2),
            m3: crop(rawTelemetry.escTemp?.m3),
            m4: crop(rawTelemetry.escTemp?.m4)
        }
    };
}

// ─── Pro Chart Rendering Configuration ───────────────────────────────────────
function getProChartOptions(yTitle = "") {
    return {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        layout: { padding: { top: 10, bottom: 10, left: 10, right: 10 } },
        plugins: {
            legend: {
                display: true,
                position: 'top',
                labels: { color: '#f8fafc', font: { family: 'Inter', size: 12, weight: 'bold' } }
            }
        },
        scales: {
            x: {
                type: 'linear',
                title: { display: true, text: 'Time (seconds)', color: '#94a3b8', font: { size: 11 } },
                ticks: { color: '#cbd5e1' },
                grid: { color: 'rgba(255, 255, 255, 0.08)' }
            },
            y: {
                title: { display: !!yTitle, text: yTitle, color: '#94a3b8', font: { size: 11 } },
                ticks: { color: '#cbd5e1' },
                grid: { color: 'rgba(255, 255, 255, 0.08)' }
            }
        }
    };
}

