function buildLineChart(canvasId, panelId, seriesList, yTitle) {
    const validSeries = seriesList.filter(s => s.data && s.data.length > 0);
    if (!validSeries.length) return;
    
    document.getElementById(panelId).style.display = 'block';
    const ctx = document.getElementById(canvasId).getContext('2d');
    if (charts[canvasId]) charts[canvasId].destroy();
    
    charts[canvasId] = new Chart(ctx, {
        type: 'line',
        data: {
            datasets: validSeries.map(s => ({
                label: s.label,
                data: s.data.map(p => ({ x: p.time, y: p.value })),
                borderColor: s.color,
                borderWidth: 2,
                borderDash: s.dash || [],
                pointRadius: 0
            }))
        },
        options: getProChartOptions(yTitle)
    });
}

// ─── Image Loader Helper (Fixes CORS and Relative Path Loading) ───────────────
function loadImageAsDataURL(src) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = 'Anonymous';
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.naturalWidth;
            canvas.height = img.naturalHeight;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            resolve({ dataUrl: canvas.toDataURL('image/png'), width: img.naturalWidth, height: img.naturalHeight });
        };
        img.onerror = () => reject(new Error(`Failed to load image at ${src}`));
        img.src = src;
    });
}

// ─── Unstretched High-Res Chart Export ────────────────────────────────────────
function renderChartToHighResImage(chartInstance) {
    const srcCanvas = chartInstance.canvas;
    
    // 1. Get the actual rendered display size (CSS pixels)
    const rect = srcCanvas.getBoundingClientRect();
    const displayWidth = rect.width || srcCanvas.offsetWidth || 800;
    const displayHeight = rect.height || srcCanvas.offsetHeight || 400;
    
    // 2. Apply high-res scaling factor based on display size
    const scale = 2.5; 
    const offCanvas = document.createElement('canvas');
    offCanvas.width = displayWidth * scale;
    offCanvas.height = displayHeight * scale;
    
    const ctx = offCanvas.getContext('2d');
    
    // 3. Fill dark background
    ctx.fillStyle = '#0b132b'; 
    ctx.fillRect(0, 0, offCanvas.width, offCanvas.height);
    
    // 4. Draw source canvas stretched cleanly to match exact scaled proportions
    ctx.drawImage(srcCanvas, 0, 0, offCanvas.width, offCanvas.height);
    
    return offCanvas.toDataURL('image/png', 1.0);
}

// ─── PDF Generation Engine ───────────────────────────────────────────────────
async function generatePDF() {
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    const margin = 18;
    
    const reporter = document.getElementById('reporterName').value.trim() || 'Sadeq Isaac (Adv. Flight Systems Engineer)';
    const globalNotes = document.getElementById('commentsGlobal').value.trim();
    const currentDate = new Date().toLocaleString();
    
    // PAGE 1: TITLE PAGE & LOG METRICS
    pdf.setFillColor(15, 23, 42);
    pdf.rect(0, 0, pageWidth, 45, 'F');
    
    pdf.setTextColor(255, 255, 255);
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(22);
    pdf.text("FLIGHT TEST & TELEMETRY REPORT", pageWidth / 2, 25, { align: "center" });
    pdf.setFontSize(10);
    pdf.setFont("helvetica", "normal");
    pdf.text("ARDUPILOT VTOL ANALYSIS SYSTEM", pageWidth / 2, 33, { align: "center" });
    
    let y = 60;
    pdf.setTextColor(30, 41, 59);
    pdf.setFontSize(11);
    pdf.setFont("helvetica", "bold");
    pdf.text("REPORT METADATA", margin, y);
    pdf.line(margin, y + 2, pageWidth - margin, y + 2);
    
    y += 10;
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(10);
    pdf.text(`Prepared By: ${reporter}`, margin, y);
    pdf.text(`Date & Time: ${currentDate}`, pageWidth - margin - 70, y);
    
    y += 15;
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(11);
    pdf.text("LOG SUMMARY & HARDWARE METRICS", margin, y);
    pdf.line(margin, y + 2, pageWidth - margin, y + 2);
    
    y += 6;
    const summaryData = [
        ['Firmware Version', flightInfo.firmware, 'Max Altitude', `${flightInfo.maxAlt.toFixed(1)} m`],
        ['Git Hash / CRC', flightInfo.gitHash, 'Max Speed', `${flightInfo.maxSpeed.toFixed(1)} m/s`],
        ['Flight Duration', `${flightInfo.duration.toFixed(1)} s`, 'Total Samples', `${flightInfo.totalSamples}`]
    ];
    
    pdf.autoTable({
        startY: y,
        head: [],
        body: summaryData,
        theme: 'grid',
        styles: { fontSize: 9.5, cellPadding: 5, textColor: [30, 41, 59] },
        columnStyles: {
            0: { fontStyle: 'bold', fillColor: [241, 245, 249], width: 38 },
            1: { width: 52 },
            2: { fontStyle: 'bold', fillColor: [241, 245, 249], width: 38 },
            3: { width: 46 }
        }
    });
    
    y = pdf.lastAutoTable.finalY + 15;
    
    if (globalNotes) {
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(11);
        pdf.text("GENERAL FLIGHT OBSERVATIONS", margin, y);
        pdf.line(margin, y + 2, pageWidth - margin, y + 2);
        y += 8;
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(10);
        const splitNotes = pdf.splitTextToSize(globalNotes, pageWidth - (margin * 2));
        pdf.text(splitNotes, margin, y);
    }
    
    // PAGE 2: OBJECTIVES & PARAMETERS
    pdf.addPage();
    y = 20;
    
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(13);
    pdf.setTextColor(15, 23, 42);
    pdf.text("1. FLIGHT TEST OBJECTIVES", margin, y);
    y += 5;
    
    const objRows = [];
    document.querySelectorAll('#objectivesTableBody tr').forEach(tr => {
        const checked = tr.querySelector('.obj-check').checked;
        if (checked) {
            const num = tr.children[1].textContent;
            const desc = tr.querySelector('.obj-desc').value;
            const prio = tr.querySelector('.obj-prio').value;
            objRows.push([num, desc, prio]);
        }
    });
    
    if (objRows.length) {
        pdf.autoTable({
            startY: y,
            head: [['#', 'Objective Description', 'Priority']],
            body: objRows,
            theme: 'striped',
            headStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
            columnStyles: { 0: { width: 15, halign: 'center' }, 2: { width: 35 } }
        });
        y = pdf.lastAutoTable.finalY + 15;
    } else {
        y += 10;
    }
    
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(13);
    pdf.text("2. AIRCRAFT & SYSTEMS CONFIGURATION MODIFICATIONS", margin, y);
    y += 5;
    
    const paramRows = [];
    document.querySelectorAll('#paramsTableBody tr').forEach(tr => {
        const name = tr.querySelector('.param-name')?.value || '';
        const defaultVal = tr.querySelector('.param-default')?.value || '';
        const actualVal = tr.querySelector('.param-val')?.value || '';
        const reason = tr.querySelector('.param-reason')?.value || '';
        
        // Push all 4 values to match your 4 autoTable header columns
        if (name.trim()) {
            paramRows.push([name, defaultVal, actualVal, reason]);
        }
    });
    
    if (paramRows.length) {
        pdf.autoTable({
            startY: y,
            head: [['PARAM', 'Default Value', 'Actual Value', 'Reference / Reason']],
            body: paramRows,
            theme: 'striped',
            headStyles: { 
                fillColor: [15, 23, 42], 
                textColor: [255, 255, 255], 
                fontStyle: 'bold' 
            },
            columnStyles: { 
                0: { cellWidth: 45, fontStyle: 'bold' }, // Parameter Name
                1: { cellWidth: 30, halign: 'center' },  // Default Value
                2: { cellWidth: 30, halign: 'center' },  // Actual Value
                3: { cellWidth: 'auto' }                // Reason / Reference
            },
            margin: { left: 14, right: 14 }
        });
    }
    
    // --- 3. CONCLUTIONS SECTION ---
    let nextY = pdf.lastAutoTable ? pdf.lastAutoTable.finalY + 12 : y + 15;
    
    // Page break check
    if (nextY > pdf.internal.pageSize.height - 50) {
        pdf.addPage();
        nextY = 20;
    }
    
    // Section Title
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(13);
    pdf.setTextColor(15, 23, 42); // #0f172a
    pdf.text("3. CONCLUTIONS", margin, nextY);
    nextY += 8;
    
    // Get conclusions value
    const rawText = document.getElementById('conclusionesText')?.value || '';
    const lines = rawText.split('\n').filter(line => line.trim() !== '');
    
    if (lines.length > 0) {
        const boxMargin = margin;
        const boxWidth = 182; // Adjust to fit page print width
        
        // Process bullet points nicely
        const formattedLines = [];
        lines.forEach(line => {
            const cleanText = line.replace(/^[\s\-\*•]+/, '').trim(); // Remove raw hyphens/asterisks
            const wrapped = pdf.splitTextToSize(`•  ${cleanText}`, boxWidth - 20);
            formattedLines.push(...wrapped);
        });
        
        const lineHeight = 6;
        const boxHeight = (formattedLines.length * lineHeight) + 12;
        
        // 1. Light Card Background
        pdf.setFillColor(248, 250, 252); // #f8fafc
        pdf.roundedRect(boxMargin, nextY, boxWidth, boxHeight, 3, 3, 'F');
        
        // 2. Left Accent Border Bar
        pdf.setFillColor(15, 23, 42); // Matching dark blue header theme
        pdf.rect(boxMargin, nextY, 3.5, boxHeight, 'F');
        
        // 3. Draw Text
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(9.5);
        pdf.setTextColor(51, 65, 85); // #334155
        
        let textY = nextY + 10;
        formattedLines.forEach(line => {
            pdf.text(line, boxMargin + 10, textY);
            textY += lineHeight;
        });
        
        nextY += boxHeight + 10;
    }
    
    // PAGE 3: PROPULSION DIAGRAM (PROPERLY LOADED & PROPORTIONED)
    pdf.addPage();
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(13);
    pdf.setTextColor(15, 23, 42);
    pdf.text("3. PROPULSION & MOTOR ROTATION SCHEMATIC", margin, 20);
    pdf.line(margin, 23, pageWidth - margin, 23);
    
    try {
        if (SCHEMATIC_BASE64 && SCHEMATIC_BASE64.startsWith("data:image")) {
            // High quality fixed box layout (174mm width x 110mm height)
            const imgWidth = pageWidth - (margin * 2);
            const imgHeight = 110; 
            
            pdf.addImage(
                SCHEMATIC_BASE64, 
                'PNG', 
                margin, 
                32, 
                imgWidth, 
                imgHeight, 
                undefined, 
                'FAST'
            );
        } else {
            throw new Error("Base64 string is missing or invalid");
        }
    } catch (e) {
        console.warn("Schematic Base64 Error: ", e);
        pdf.setFontSize(10);
        pdf.setTextColor(239, 68, 68);
        pdf.text("Note: Propulsion schematic diagram Base64 data could not be rendered.", margin, 35);
    }
    
    // SUBSEQUENT PAGES: UNSTRETCHED HIGH-RES CHARTS
    const chartPanels = [
        { id: 'baroGpsChart', title: 'Altitude Performance (BARO vs GPS)', commentId: 'commentBaroGps' },
        { id: 'imuChart', title: 'Vertical Dynamic Acceleration (IMU AccZ)', commentId: 'commentImu' },
        { id: 'airspeedChart', title: 'Airspeed vs Ground Speed (ARSP vs GPS)', commentId: 'commentAirspeed' },
        { id: 'rollChart', title: 'Roll Attitude Response (Actual vs Desired)', commentId: 'commentRoll' },
        { id: 'pitchChart', title: 'Pitch Attitude Response (Actual vs Desired)', commentId: 'commentPitch' },
        { id: 'yawChart', title: 'Yaw Attitude Response (Actual vs Desired)', commentId: 'commentYaw' },
        { id: 'leftAilChart', title: 'Left Aileron Servo Feedback & Command', commentId: 'commentLeftAil' },
        { id: 'rightAilChart', title: 'Right Aileron Servo Feedback & Command', commentId: 'commentRightAil' },
        { id: 'leftRudChart', title: 'Left Ruddervator Servo Feedback & Command', commentId: 'commentLeftRud' },
        { id: 'rightRudChart', title: 'Right Ruddervator Servo Feedback & Command', commentId: 'commentRightRud' },
        { id: 'escRpmChart', title: 'VTOL Quad Motors — RPM Dynamics', commentId: 'commentEscRpm' },
        { id: 'escCurrChart', title: 'VTOL Quad Motors — Current Consumption', commentId: 'commentEscCurr' },
        { id: 'escTempChart', title: 'VTOL Quad Motors — Thermal Status', commentId: 'commentEscTemp' }
    ];
    
    for (const panel of chartPanels) {
        if (!charts[panel.id]) continue;
        
        pdf.addPage();
        pdf.setTextColor(15, 23, 42);
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(12);
        pdf.text(panel.title, margin, 18);
        pdf.line(margin, 21, pageWidth - margin, 21);
        
        const highResDataUrl = renderChartToHighResImage(charts[panel.id]);
        
        // Fixed dimensions to preserve 16:9 widescreen plot aspect ratio (174mm x 90mm)
        const pdfPlotW = pageWidth - (margin * 2);
        const pdfPlotH = 90;
        
        pdf.addImage(highResDataUrl, 'PNG', margin, 26, pdfPlotW, pdfPlotH);
        
        // Comment Box Placement Directly Below Plot
        const comment = document.getElementById(panel.commentId)?.value.trim();
        if (comment) {
            const commentY = 124;
            pdf.setFillColor(248, 250, 252);
            pdf.rect(margin, commentY, pdfPlotW, 35, 'F');
            pdf.setDrawColor(203, 213, 225);
            pdf.rect(margin, commentY, pdfPlotW, 35, 'D');
            
            pdf.setFont("helvetica", "bold");
            pdf.setFontSize(9.5);
            pdf.setTextColor(51, 65, 85);
            pdf.text("Engineering Comments & Observations:", margin + 4, commentY + 7);
            
            pdf.setFont("helvetica", "normal");
            pdf.setFontSize(9);
            pdf.setTextColor(71, 85, 105);
            const splitComment = pdf.splitTextToSize(comment, pdfPlotW - 8);
            pdf.text(splitComment, margin + 4, commentY + 15);
        }
    }
    
    pdf.save(`Flight_Telemetry_Report_${new Date().toISOString().slice(0, 10)}.pdf`);
}

function exportNativePDF() {
    // Hide UI controls temporarily
    const buttons = document.querySelectorAll('button, input[type="file"], .no-print');
    buttons.forEach(b => b.style.display = 'none');
    
    // Trigger browser print menu
    window.print();
    
    // Restore UI controls
    buttons.forEach(b => b.style.display = '');
}